contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We send an amount and call Put with some lock time. We assert that if the Put call does not revert,
    // then the stored per-account balance for this contract (as seen through the public getter) is >= the
    // previous stored balance, and address(c).balance increased by at least the sent amount.
    function run(uint _lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read prior observed values
        // Acc is a public mapping to a struct; Solidity auto-generates a getter Acc(address) returning (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // call Put with value 'amount'
        try c.Put{value: amount}(_lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the call did not revert, then the stored balance for this caller must be >= beforeBal,
        // and the contract's ETH balance must have increased by at least amount.
        // If it reverted, we place no requirement (allowed any behavior).
        assert(reverted || (afterBal >= beforeBal && afterContractBal >= beforeContractBal + amount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will prepare the contract so that this test contract has enough recorded balance and meets MinSum and unlockTime
    // then call Collect and assert that on a successful call the stored balance decreased by exactly the requested amount
    function run(uint depositLock, uint depositAmount, uint collectAmount, uint minSum, address logAddr) public payable {
        // require we have ETH to fund deposits
        require(address(this).balance >= depositAmount + 1);

        // 1) Set MinSum and LogFile before Initialized; these calls may revert if intitalized is true, but c is fresh so ok
        // Both SetMinSum and SetLogFile are nonReentrant_ and will only succeed before Initialized()
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        // do not call Initialized so we can still setup

        // 2) Make a deposit by calling Put (or fallback). Use payable call with depositAmount.
        // Read recorded balance before deposit
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // call Put with depositLock and value depositAmount
        c.Put{value: depositAmount}(depositLock);

        // After deposit, recorded balance should be >= beforeBal (but we won't assert that here to avoid hitting add_uint256)
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // 3) Fast-forward condition: to make Collect succeed we need midBal >= minSum, midBal >= collectAmount, and block.timestamp > unlockTime.
        // We cannot advance block.timestamp; instead, ensure depositLock is zero so unlockTime was set to max(prev, block.timestamp+0) => >= block.timestamp.
        // To satisfy block.timestamp > unlockTime we require that midUnlock < block.timestamp.
        // Since we cannot modify the environment, require that midUnlock < block.timestamp holds now.
        require(midBal >= minSum && midBal >= collectAmount && midUnlock < block.timestamp);

        // Read balances before calling Collect
        (uint preCollectUnlock, uint preCollectBal) = c.Acc(address(this));
        uint preCollectContractBal = address(c).balance;

        bool reverted;
        // attempt Collect; it may still revert for some reason, capture that
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint postCollectUnlock, uint postCollectBal) = c.Acc(address(this));
        uint postCollectContractBal = address(c).balance;

        // If Collect succeeded then: recorded balance decreased by exactly collectAmount AND contract balance decreased by at least collectAmount
        // If reverted then no requirement.
        assert(reverted || (preCollectBal == postCollectBal + collectAmount && preCollectContractBal >= postCollectContractBal + collectAmount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that once Initialized() has been called, SetMinSum cannot succeed anymore.
    // Parameters: a value to attempt to set as MinSum after initialization.
    function run(uint newMin) public payable {
        // 1) Before calling Initialized, SetMinSum should be allowed (contract is fresh), so call it once to ensure normal behavior.
        // We don't check its effect; we just ensure it doesn't revert here so that Initialized transition is meaningful.
        bool preReverted;
        try c.SetMinSum(newMin) {
            preReverted = false;
        } catch {
            preReverted = true;
        }

        // If the first SetMinSum call reverted unexpectedly, we still proceed to call Initialized to reach the asserted property.
        // 2) Call Initialized to flip the flag.
        c.Initialized();

        // 3) Now attempt to call SetMinSum again; it SHOULD revert because intitalized was set.
        bool postReverted;
        try c.SetMinSum(newMin) {
            postReverted = false;
        } catch {
            postReverted = true;
        }

        // General rule: after Initialized() has been called, SetMinSum must revert for any input.
        // We allow the pre-Initialized call to have either reverted or not (some implementations might restrict it),
        // but require that the post-Initialized attempt does revert.
        assert(postReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use msg.sender of calls to c as this contract. run is payable to allow sending Ether to c.
    function run(uint setMin, uint putLock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount + 1 wei); // ensure we can fund Put; +1 to avoid zero-value edge-case

        // Ensure contract has a LogFile and MinSum can be set before Initialized is called
        // Set MinSum to setMin
        c.SetMinSum(setMin);

        // Make a Put call to deposit putAmount and set unlock time
        // Need to send Ether from this contract to c
        c.Put{value: putAmount}(putLock);

        // Read holder info via public Acc getter: returns (unlockTime, balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Precondition: ensure the holder balance is strictly less than MinSum to check the rule
        // If not, adjust by requiring the test parameters to make it so; otherwise the assert will be about a different case.
        require(beforeBalance < c.MinSum());

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule: if beforeBalance < MinSum then Collect must not transfer Ether out of the contract to this address
        // Equivalent observable condition: contract balance must not decrease OR the recorded holder balance must not decrease.
        // We assert that either the contract balance did not decrease, or the recorded holder balance did not decrease, or the call reverted.
        assert(reverted || afterCbal >= beforeCbal || afterBalance >= beforeBalance);
    }

    // allow receiving Ether for funding Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: set MinSum, Put enough funds so balance >= MinSum, ensure unlockTime is in the past,
    // then call Collect and observe behavior. The assertion states that if Collect did not revert
    // and preconditions held, then both Acc balance and address(c).balance decreased by exactly collectAmt.

    function run(uint minSum, uint putLock, uint putAmount, uint collectAmt) public payable {
        // Need funds to Put
        require(address(this).balance >= putAmount);

        // Initialize MinSum and LogFile address before Initialized() is called
        c.SetMinSum(minSum);

        // Make a deposit: send putAmount to c and set lock to putLock
        c.Put{value: putAmount}(putLock);

        // Read holder info and contract balance before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Preconditions for the rule we want to check:
        // 1) holder balance >= MinSum
        // 2) holder balance >= collectAmt (otherwise Collect cannot succeed)
        // 3) block.timestamp > unlockTime (unlockTime strictly in past) -> we simulate by requiring putLock == 0 so Put set unlockTime = now
        //    then require that block.timestamp > beforeUnlock; since beforeUnlock equals now from Put when putLock==0,
        //    we cannot make block.timestamp > now in the same transaction. To observe an unlockTime in the past,
        //    we instead rely on Put having set unlockTime earlier by using putLock = 0 and then we check the behavior
        //    when collectAmt is zero (Collect of 0 can succeed if other conditions hold). So we'll restrict to collectAmt > 0
        // To avoid depending on time progression, we choose the case putLock == 0 and require(block.timestamp == beforeUnlock),
        // and then only allow collectAmt == 0 to ensure Collect can proceed when unlock condition requires strict >; but Collect requires block.timestamp > acc.unlockTime,
        // so with equal timestamps Collect would revert. Therefore to get a successful Collect without time travel, we instead rely on the fallback path:
        // call Put with putLock = 0 earlier (unlockTime = now), then circumvent time by not calling Collect unless the unlockTime is in the past.
        // Since we cannot advance block.timestamp, we craft the test to only assert the invariant in the case Collect succeeded (observably). Thus we do not require unlockTime condition here,
        // but we will record whether Collect reverted and only apply the exact-change rule when Collect succeeded and the preconditions (balance>=MinSum and balance>=collectAmt) held before the call.

        // Ensure the stored balance meets numeric preconditions to consider Collect success path
        require(beforeBalance >= minSum);
        require(beforeBalance >= collectAmt);

        // Attempt Collect and capture revert status
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // If Collect did not revert AND the preconditions (balance>=MinSum and balance>=collectAmt) held before the call,
        // then the caller's recorded balance must have decreased by exactly collectAmt and the contract's balance must have decreased by exactly collectAmt.
        // We assert that either Collect reverted, or BOTH decreases happened exactly.
        assert(
            reverted
            || (beforeBalance >= collectAmt
                && beforeBalance - afterBalance == collectAmt
                && beforeCbal - afterCbal == collectAmt)
        );
    }

    // Allow receiving Ether for funding Put
    receive() external payable {}
}

