contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that whenever a Put call succeeds, the on-chain recorded holder balance for this contract
    // increases by at least the sent value. To avoid arithmetic under/overflow in the test, we express
    // the post-condition as: after_balance >= before_balance and the increase is >= value_sent.
    // The function is payable so the harness can provide Ether for the Put call.
    function run(uint lockTime, uint putAmount) public payable {
        require(address(this).balance >= putAmount);

        // Observe balance before Put
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Call Put and record whether it reverted
        bool putReverted;
        try c.Put{value: putAmount}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // If Put succeeded, then the recorded holder balance for this address must have increased by at least putAmount,
        // and the contract's Ether balance must have increased by at least putAmount as well.
        // Expressed without subtraction to avoid underflow: afterBalance >= beforeBalance and (afterBalance - beforeBalance) >= putAmount
        // To avoid subtraction in the assert itself, we rewrite: afterBalance >= beforeBalance + putAmount.
        assert(
            putReverted
            || (afterBalance >= beforeBalance + putAmount && afterCbal >= beforeCbal + putAmount)
        );
    }

    // Allow receiving Ether to fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use params: initial deposit amount to Put, lock time for Put, MinSum to set before Initialized,
    // collect amount to attempt, and a flag whether to call Initialized before Collect.
    function run(uint putAmount, uint putLock, uint minSumVal, uint collectAmount, bool callInitialized) public payable {
        require(address(this).balance >= putAmount, "insufficient balance for put");
        // Ensure fresh setup: set MinSum before locking Initialized. Both SetMinSum and SetLogFile require not initialized.
        // Provide a dummy LogFile by using address(0) which is allowed (no call occurs in SetLogFile itself),
        // but SetLogFile will accept any address. Call SetMinSum and SetLogFile.
        c.SetMinSum(minSumVal);
        c.SetLogFile(address(0));
        // Optionally mark initialized
        if (callInitialized) {
            c.Initialized();
        }

        // Record balances before Put
        uint beforeCbal = address(c).balance;
        // Do a Put from this contract to c, sending putAmount
        c.Put{value: putAmount}(putLock);
        uint afterPutCbal = address(c).balance;

        // Now attempt Collect for collectAmount and record whether it reverted and balances
        bool reverted;
        uint beforeCollectCbal = afterPutCbal;
        uint beforeMyBal = address(this).balance;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterCollectCbal = address(c).balance;
        uint afterMyBal = address(this).balance;

        // Read the public holder record for this contract's address from c
        (uint unlockTime, uint balance) = c.Acc(address(this));
        uint minSumObserved = c.MinSum();

        // General rule asserted in one boolean:
        // If the holder's recorded balance before/after (we observe current balance) is < MinSum, then Collect must have reverted or no ETH should have left the contract c.
        // If holder's recorded balance >= MinSum and Collect did not revert, then c's balance must have decreased by exactly collectAmount and the holder's recorded balance must be at least collectAmount less than before (i.e., new balance = old balance - collectAmount).
        // Since we only observe the current stored balance after operations, we express constraints combining observed values and revert flag.
        // Formally:
        // - If balance < minSumObserved then (reverted == true) || (afterCollectCbal >= beforeCollectCbal)
        // - Else (balance >= minSumObserved) implies (reverted == false) implies (beforeCollectCbal - afterCollectCbal == collectAmount && beforePutCbal + 0 /*no other reads*/ >= 0) and that the stored balance decreased by collectAmount: (balance + collectAmount <= /* previous recorded before collect is unknown, but after a successful collect the current stored balance equals previous - collectAmount; we can assert that if not reverted then address(c).balance decreased by collectAmount AND recorded balance + collectAmount >= collectAmount)
        // To keep a single assert and avoid underflow, encode as:
        bool ruleLeft = (balance < minSumObserved) ? (reverted || (afterCollectCbal >= beforeCollectCbal)) : true;
        bool ruleRight = (balance >= minSumObserved && !reverted) ? (beforeCollectCbal >= afterCollectCbal && (beforeCollectCbal - afterCollectCbal) == collectAmount && balance + collectAmount >= collectAmount) : true;

        assert(ruleLeft && ruleRight);
    }

    receive() external payable {}
}

